B.ajJ=new A.lW("User summary","SELECT u.id, u.username, u.email,\n       u.created_at, u.last_login,\n       COUNT(DISTINCT r.id) AS runs,\n       COALESCE(SUM(r.total_tokens),0) AS tokens\nFROM users u\nLEFT JOIN agent_runs r ON r.user_id = u.id\nGROUP BY u.id\nORDER BY runs DESC\nLIMIT 50")
B.ajn=new A.lW("Recent failed runs","SELECT r.id, u.username, r.title, r.status,\n       r.error, r.created_at\nFROM agent_runs r\nJOIN users u ON u.id = r.user_id\nWHERE r.status = 'failed'\nORDER BY r.created_at DESC\nLIMIT 50")
B.ajc=new A.lW("Artifact storage by user","SELECT u.username,\n       COUNT(a.id) AS files,\n       SUM(a.byte_size) AS bytes,\n       ROUND(SUM(a.byte_size) / 1048576.0, 2) AS mb\nFROM users u\nLEFT JOIN artifacts a ON a.user_id = u.id\nGROUP BY u.id\nORDER BY bytes DESC")
B.aj6=new A.lW("Active sessions","SELECT u.username, s.ip_address,\n       s.user_agent, s.created_at, s.last_seen_at\nFROM user_sessions s\nJOIN users u ON u.id = s.user_id\nWHERE s.revoked_at IS NULL\n  AND s.expires_at > datetime('now')\nORDER BY s.last_seen_at DESC\nLIMIT 50")
B.aj9=new A.lW("Runs per day (30 days)","SELECT DATE(created_at) AS day,\n       COUNT(*) AS runs,\n       COALESCE(SUM(total_tokens),0) AS tokens\nFROM agent_runs\nWHERE created_at >= datetime('now', '-30 days')\nGROUP BY day\nORDER BY day DESC")
B.ajr=new A.lW("Most used agents","SELECT a.slug, a.display_name, u.username AS owner,\n       COUNT(r.id) AS runs\nFROM agents a\nJOIN users u ON u.id = a.user_id\nLEFT JOIN agent_runs r ON r.agent_id = a.id\nGROUP BY a.id\nORDER BY runs DESC\nLIMIT 20")
B.aja=new A.lW("Integration connections","SELECT u.username, ic.provider_key,\n       ic.status, ic.account_email, ic.last_connected_at\nFROM integration_connections ic\nJOIN users u ON u.id = ic.user_id\nORDER BY ic.last_connected_at DESC\nLIMIT 50")
B.ajR=new A.lW("Who manages whom","SELECT managed.username AS account,\n       manager.username AS managed_by,\n       d.allowed_permissions_json AS allowed,\n       d.created_at AS since\nFROM user_delegations d\nJOIN users managed ON managed.id = d.managed_user_id\nJOIN users manager ON manager.id = d.manager_user_id\nORDER BY manager.username, managed.username")
B.ajQ=new A.lW("All tables","SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
B.aj3=new A.lW("Table info (users)","SELECT * FROM pragma_table_info('users')")
